"""Individual XML source decisions. This file alone admits no catalog change.

Literal editions belong only to the stated paragraphs/cohorts. A named KING
estimator is not proof of the standalone executable. Existing review records
are retained verbatim by the cumulative transition, not rewritten here.
"""


def E(literal, indices, context):
    return dict(literal=literal, paragraph_indices=indices, context=context)


def R(indices, editions, kind, summary, caution, overlap, remaining, prior=False, additional=None):
    result = dict(paragraph_indices=indices, reported_editions=editions, role=kind,
                use_summary=summary, required_caution=caution,
                qualified_component_overlap=overlap, remaining_roles=remaining,
                preserve_prior_review=prior)
    if additional is not None:
        result['additional_primary_evidence'] = [additional]
    return result


